MSD.cls('.m-tangle', 'draw', false);
MSD.cls('.m-fan', 'draw', false);
MSD.cls('.m-fan', 'live', false);
MSD.cls('.m-fan', 'flow', false);
MSD.cls('.m-conn', 'req', false);
MSD.cls('.m-conn', 'res', false);
MSD.cls('.m-node', 'hot', false);
MSD.cls('.m-node', 'back', false);
MSD.cls('.m-tool', 'hot', false);
MSD.cls('#m-ask', 'live', false);
MSD.cls('#m-verdict', 'bad', false);
MSD.cls('#m-verdict', 'good', false);
MSD.cls('#m-verdict', 'win', false);
MSD.cls('#m-verdict', 'num', false);
MSD.cls('#m-why', 'on', false);
MSD.cls('#m-stack', 'dim', false);
MSD.q('#m-vt2').textContent = '';
// One-shot beats leave their class behind. Clearing them on the cut stops
// a punch or a shake from a previous stage bleeding into this one's frame.
MSD.cls('.msd-punch', 'msd-punch', false);
MSD.cls('.msd-flash', 'msd-flash', false);
MSD.cls('.msd-shake', 'msd-shake', false);

MSD.cls('.m-tool', 'on', false);
MSD.cls('.m-tool', 'std', false);
MSD.cls('.m-tool', 'mess', false);
MSD.cls('#m-mcp', 'on', false);
MSD.cls('#m-client, #m-server', 'on', false);
MSD.cls('#m-ask', 'on', false);
MSD.cls('#m-user, #m-ai', 'on', false);
MSD.cls('#m-verdict', 'on', false);
MSD.q('#m-ask-t').textContent = '';

MSD.after(80, function(){ MSD.cls('#m-ask', 'on', true); MSD.cls('#m-ask', 'live', true); MSD.sfx.blip(0); });
MSD.after(200, function(){
  MSD.type('#m-ask-t', 'How can AI use GitHub, my database, my files and Slack?', 26);
});
MSD.after(340, function(){ MSD.cls('#m-user', 'on', true); MSD.sfx.blip(1); });
MSD.after(560, function(){ MSD.cls('#m-c1', 'req', true); });
MSD.after(700, function(){ MSD.cls('#m-ai', 'on', true); MSD.sfx.blip(2); });
MSD.after(1250, function(){ MSD.cls('#m-ai', 'hot', true); });

// The tools are on screen from the first frame, but dim: they exist, the
// assistant just has no route to them. The hole below it is that route.
MSD.after(1700, function(){
  MSD.cls('#m-void', 'on', true);
  MSD.cls('#m-ai', 'hot', false);
  MSD.sfx.error();
});
MSD.after(2000, function(){ MSD.shake('#m-void'); });
MSD.after(2200, function(){
  MSD.cls('#m-verdict', 'on', true);
  MSD.cls('#m-verdict', 'bad', true);
  MSD.q('#m-vic').textContent = '\u2715';
  MSD.q('#m-vt').textContent = 'The tools are right there. Nothing reaches them.';
});

MSD.cls('.m-tangle', 'draw', false);
MSD.cls('.m-fan', 'draw', false);
MSD.cls('.m-fan', 'live', false);
MSD.cls('.m-fan', 'flow', false);
MSD.cls('.m-conn', 'req', false);
MSD.cls('.m-conn', 'res', false);
MSD.cls('.m-node', 'hot', false);
MSD.cls('.m-node', 'back', false);
MSD.cls('.m-tool', 'hot', false);
MSD.cls('#m-ask', 'live', false);
MSD.cls('#m-verdict', 'bad', false);
MSD.cls('#m-verdict', 'good', false);
MSD.cls('#m-verdict', 'win', false);
MSD.cls('#m-verdict', 'num', false);
MSD.cls('#m-why', 'on', false);
MSD.cls('#m-stack', 'dim', false);
MSD.q('#m-vt2').textContent = '';
// One-shot beats leave their class behind. Clearing them on the cut stops
// a punch or a shake from a previous stage bleeding into this one's frame.
MSD.cls('.msd-punch', 'msd-punch', false);
MSD.cls('.msd-flash', 'msd-flash', false);
MSD.cls('.msd-shake', 'msd-shake', false);

MSD.cls('#m-void', 'on', false);
MSD.cls('#m-mcp', 'on', false);
MSD.cls('#m-client, #m-server', 'on', false);
MSD.cls('#m-ask, #m-user, #m-ai', 'on', true);
MSD.cls('.m-tool', 'std', false);
MSD.cls('.m-tool', 'on', true);
MSD.cls('.m-tool', 'mess', true);
MSD.cls('#m-ai', 'hot', true);
MSD.q('#m-ask-t').textContent = 'Connect me to my tools.';

// One tangled wire per tool, drawn fast enough to feel like it is
// getting out of hand rather than being carefully assembled.
for(var i = 1; i <= 7; i++){
  (function(i){
    MSD.after(120 + i * 190, function(){
      MSD.cls('#m-g' + i, 'draw', true);
      MSD.sfx.step(i);
    });
  })(i);
}

MSD.after(1700, function(){
  MSD.cls('#m-verdict', 'on', true);
  MSD.cls('#m-verdict', 'bad', true);
  MSD.cls('#m-verdict', 'num', true);
  MSD.q('#m-vic').textContent = '\u2715';
  MSD.q('#m-vt').textContent = '7 AI apps \u00d7 7 tools =';
  MSD.q('#m-vt2').textContent = 'integrations to build and maintain';
  MSD.count('#m-vnum', 49, 900);
  MSD.sfx.riser(900);
});
MSD.after(2650, function(){ MSD.shake('#m-verdict'); MSD.punch('#m-ai', 3); });

MSD.cls('.m-tangle', 'draw', false);
MSD.cls('.m-fan', 'draw', false);
MSD.cls('.m-fan', 'live', false);
MSD.cls('.m-fan', 'flow', false);
MSD.cls('.m-conn', 'req', false);
MSD.cls('.m-conn', 'res', false);
MSD.cls('.m-node', 'hot', false);
MSD.cls('.m-node', 'back', false);
MSD.cls('.m-tool', 'hot', false);
MSD.cls('#m-ask', 'live', false);
MSD.cls('#m-verdict', 'bad', false);
MSD.cls('#m-verdict', 'good', false);
MSD.cls('#m-verdict', 'win', false);
MSD.cls('#m-verdict', 'num', false);
MSD.cls('#m-why', 'on', false);
MSD.cls('#m-stack', 'dim', false);
MSD.q('#m-vt2').textContent = '';
// One-shot beats leave their class behind. Clearing them on the cut stops
// a punch or a shake from a previous stage bleeding into this one's frame.
MSD.cls('.msd-punch', 'msd-punch', false);
MSD.cls('.msd-flash', 'msd-flash', false);
MSD.cls('.msd-shake', 'msd-shake', false);

MSD.cls('#m-void', 'on', false);
MSD.cls('#m-client, #m-server', 'on', false);
MSD.cls('#m-ask, #m-user, #m-ai', 'on', true);
MSD.cls('.m-tool', 'on', true);
MSD.cls('.m-tool', 'mess', false);
MSD.cls('#m-mcp', 'on', false);
MSD.q('#m-ask-t').textContent = 'Connect me to my tools.';

// The tangle is already off via RESET — it fades as the box drops in,
// which is the whole point of the stage.
MSD.after(120, function(){ MSD.sfx.whoosh(false); });
MSD.after(420, function(){ MSD.cls('#m-mcp', 'on', true); MSD.sfx.lock(); });
MSD.after(700, function(){ MSD.cls('#m-c2', 'req', true); MSD.flash('#m-mcp'); });

// Same seven endpoints as the tangle, now reached by one fan.
for(var i = 1; i <= 7; i++){
  (function(i){
    MSD.after(950 + i * 110, function(){
      MSD.cls('#m-f' + i, 'draw', true);
      MSD.cls('#m-t' + i, 'std', true);
      MSD.sfx.blip(i);
    });
  })(i);
}

MSD.after(1950, function(){
  MSD.cls('#m-verdict', 'on', true);
  MSD.cls('#m-verdict', 'good', true);
  MSD.q('#m-vic').textContent = '\u2713';
  MSD.q('#m-vt').textContent = 'One standard protocol \u00b7 7 connectors, not 49';
  MSD.sfx.sparkle();
});
MSD.after(2400, function(){ MSD.punch('#m-mcp', 4); });

MSD.cls('.m-tangle', 'draw', false);
MSD.cls('.m-fan', 'draw', false);
MSD.cls('.m-fan', 'live', false);
MSD.cls('.m-fan', 'flow', false);
MSD.cls('.m-conn', 'req', false);
MSD.cls('.m-conn', 'res', false);
MSD.cls('.m-node', 'hot', false);
MSD.cls('.m-node', 'back', false);
MSD.cls('.m-tool', 'hot', false);
MSD.cls('#m-ask', 'live', false);
MSD.cls('#m-verdict', 'bad', false);
MSD.cls('#m-verdict', 'good', false);
MSD.cls('#m-verdict', 'win', false);
MSD.cls('#m-verdict', 'num', false);
MSD.cls('#m-why', 'on', false);
MSD.cls('#m-stack', 'dim', false);
MSD.q('#m-vt2').textContent = '';
// One-shot beats leave their class behind. Clearing them on the cut stops
// a punch or a shake from a previous stage bleeding into this one's frame.
MSD.cls('.msd-punch', 'msd-punch', false);
MSD.cls('.msd-flash', 'msd-flash', false);
MSD.cls('.msd-shake', 'msd-shake', false);

MSD.cls('#m-void', 'on', false);
MSD.cls('#m-ask, #m-user, #m-ai', 'on', true);
MSD.cls('.m-tool', 'on', true);
MSD.cls('.m-tool', 'std', true);
MSD.cls('.m-fan', 'draw', true);
MSD.q('#m-ask-t').textContent = 'Connect me to my tools.';

// The box splits along its own seam into the two halves it was made of.
MSD.cls('#m-mcp', 'on', true);
MSD.cls('#m-client, #m-server', 'on', false);
MSD.after(500, function(){
  MSD.cls('#m-mcp', 'on', false);
